// 原Travel救助与Common逐批执行合看；不把此组件当永久运输账或商铺到货验收。
#define main private_shop_original_travel_expense_main
#include "private_shop_travel_expense_source_test.cpp"
#undef main
#include "resident/domains/commerce/freight/private_shop_travel_rescue_loss.hpp"
namespace {
// 真起行、实扣路费、原救助改种和两次原Action减步；不直接种完成载荷。
StableId prepare_rescue(Fixture& f,bool personal=true){
 f.common_catalog->items.insert("grain",{"grain",1,1});ResourceRecipe lots;
 if(personal){lots.operations.push_back(AddLot{"bag.carrier","grain",21,{Owner::Kind::actor,"carrier",{}},{}});lots.operations.push_back(AddLot{"bag.carrier","grain",9,{Owner::Kind::actor,"carrier",{}},{}});}
 lots.operations.push_back(AddLot{"bag.carrier","grain",19,{Owner::Kind::actor,"other",{}},{}});require(f.common.apply_resources(lots).ok,"original mixed-owner cargo");
 const auto id=f.begin("carrier","B");require(step_travel(f.common,f.travel,f.catalog,f.services,id).ok,"actual charged movement");require(f.common.apply_resources({{WalletDelta{"wallet.carrier",-f.funds("carrier"),true}},{}}).ok,"original payer emptied by actual expense");require(preview_rescue(f.common,f.travel,f.catalog,f.services,"carrier").ok,"original rescue qualification");require(begin_rescue(f.common,f.travel,"carrier").ok,"actual rescue replacement");
 for(int n=0;n<2;++n){ActionMutation step;step.action=*f.common.action(id);step.remaining_ticks=step.action.remaining_ticks-1;require(f.common.apply_action(step).ok,"actual rescue decrement");if(!n)++f.common.state().identity.tick;}
 return id;
}
// 一次原完成只认本人的各批floor损耗，原预约与他人物品均不被读口改写。
void original_loss_and_tamper(){
 Fixture f;const auto id=prepare_rescue(f);const auto first=f.common.inventory("bag.carrier")->lots.front().id;ReserveLots reserve;reserve.inventory_id="bag.carrier";reserve.item_id="grain";reserve.quantity=21;reserve.owners={{Owner::Kind::actor,"carrier",{}}};reserve.action_id=id;require(f.common.apply_resources({{reserve},{}}).ok,"original reservation on personal cargo");
 require(f.common.begin_resource_execution_capture().ok,"start original Common capture");auto boundary=capture_private_shop_travel_rescue_loss_boundary(f.common,f.travel,f.catalog,id);require(boundary.ok,"capture ready rescue boundary");const auto original_next=f.common.state().next_instance_id;std::optional<TravelRescueCompletionDraft> completion;require(finish_rescue(f.common,f.travel,f.catalog,id,&completion).ok&&completion.has_value(),"actual rescue finish emits successful snapshot");
 auto read=read_private_shop_travel_rescue_loss(f.common,f.travel,f.catalog,boundary.value,*completion);require(read.ok,"match real AdjustLots and original completion");check(read.value.personal_losses.size()==2&&read.value.personal_losses[0].lost_quantity==2&&read.value.personal_losses[1].lost_quantity==0,"per-lot loss includes distinct zero leg");check(read.value.personal_losses[0].lot_id==first&&f.common.inventory("bag.carrier")->lots[0].reserved_by.id==id,"actual original reserved batch retained");check(f.common.inventory("bag.carrier")->lots[2].quantity==19&&f.funds("carrier")==0&&f.common.state().next_instance_id==original_next,"foreign batch and actual money/ID unchanged");check(std::get<SettlementLocation>(completion->after_location).settlement_id=="A","rescue returns actual origin, not destination B");
 auto bad=*completion;bad.applied_adjustment.lots.pop_back();check(!read_private_shop_travel_rescue_loss(f.common,f.travel,f.catalog,boundary.value,bad).ok,"omitting original zero leg rejected");bad=*completion;bad.source_tick++;check(!read_private_shop_travel_rescue_loss(f.common,f.travel,f.catalog,boundary.value,bad).ok,"future completion tick rejected");bad=*completion;bad.after_location=SettlementLocation{"B","B.exit"};check(!read_private_shop_travel_rescue_loss(f.common,f.travel,f.catalog,boundary.value,bad).ok,"destination cannot replace original return");bad=*completion;bad.after_inventory.lots[2].quantity--;check(!read_private_shop_travel_rescue_loss(f.common,f.travel,f.catalog,boundary.value,bad).ok,"foreign loss snapshot rejected");
 auto wrong_boundary=boundary.value;wrong_boundary.action.participants.push_back("other");check(!read_private_shop_travel_rescue_loss(f.common,f.travel,f.catalog,wrong_boundary,*completion).ok,"actual action participants cannot be changed");
 const auto prior=f.common.state().inventories.find("bag.carrier")->lots[0].reserved_by;f.common.state().inventories.find("bag.carrier")->lots[0].reserved_by={};check(!read_private_shop_travel_rescue_loss(f.common,f.travel,f.catalog,boundary.value,*completion).ok,"unrecorded current reservation mutation rejected");f.common.state().inventories.find("bag.carrier")->lots[0].reserved_by=prior;
 require(f.common.apply_resources({{WalletDelta{"wallet.carrier",0,true}},{}}).ok,"real extra zero money recipe");check(!read_private_shop_travel_rescue_loss(f.common,f.travel,f.catalog,boundary.value,*completion).ok,"another actual recipe cannot join rescue loss");
}
// 没有本人货时，原writer仍执行空Adjust并加revision；不能虚构一笔损耗或付款。
void no_personal_loss(){Fixture f;const auto id=prepare_rescue(f,false);require(f.common.begin_resource_execution_capture().ok,"capture empty personal case");auto b=capture_private_shop_travel_rescue_loss_boundary(f.common,f.travel,f.catalog,id);require(b.ok,"empty personal boundary");std::optional<TravelRescueCompletionDraft> done;require(finish_rescue(f.common,f.travel,f.catalog,id,&done).ok&&done.has_value(),"original empty personal adjust");auto read=read_private_shop_travel_rescue_loss(f.common,f.travel,f.catalog,b.value,*done);check(read.ok&&read.value.personal_losses.empty()&&read.value.actual_recipe.operations[0].lot_flows.empty(),"actual empty loss has no invented leg");check(f.common.inventory("bag.carrier")->revision==b.value.before_inventory.revision+1&&f.common.inventory("bag.carrier")->lots[0].quantity==19,"empty adjust retains original revision rule and foreign cargo");}
// 捕获结束后同址重开不能用旧边界；完整原保存点可撤回真实已扣货与返城。
void lifecycle_and_rollback(){Fixture f;const auto id=prepare_rescue(f);check(!capture_private_shop_travel_rescue_loss_boundary(f.common,f.travel,f.catalog,id).ok,"capture lifecycle required");require(f.common.begin_resource_execution_capture().ok,"begin rollback capture");auto b=capture_private_shop_travel_rescue_loss_boundary(f.common,f.travel,f.catalog,id);require(b.ok,"original rollback boundary");auto save=f.common.begin_savepoint();require(save.ok,"original full Common savepoint");std::optional<TravelRescueCompletionDraft> done;require(finish_rescue(f.common,f.travel,f.catalog,id,&done).ok&&done.has_value(),"actual cargo loss before outer abort");require(read_private_shop_travel_rescue_loss(f.common,f.travel,f.catalog,b.value,*done).ok,"same-candidate source readable before outer abort");require(f.common.rollback_savepoint(save.value).ok,"original savepoint rolls back location and cargo");check(f.common.inventory("bag.carrier")->lots[0].quantity==21&&std::holds_alternative<OnRouteLocation>(f.common.actor("carrier")->location)&&f.common.resource_execution_drafts().empty(),"aborted original writes and draft all restored");check(!read_private_shop_travel_rescue_loss(f.common,f.travel,f.catalog,b.value,*done).ok,"stale successful snapshot cannot survive actual rollback");require(f.common.finish_resource_execution_capture().ok,"end original capture");require(f.common.begin_resource_execution_capture().ok,"reopen same Common capture");require(finish_rescue(f.common,f.travel,f.catalog,id,&done).ok&&done.has_value(),"same values under new real capture");check(!read_private_shop_travel_rescue_loss(f.common,f.travel,f.catalog,b.value,*done).ok,"old boundary cannot consume same-address restarted capture");}
}
int main(){try{original_loss_and_tamper();no_personal_loss();lifecycle_and_rollback();}catch(const std::exception& e){check(false,e.what());}std::cout<<"PRIVATE_SHOP_RESCUE_LOSS_CHECKS="<<checks<<" FAILURES="<<failures<<'\n';return failures?1:0;}
